/// First character of `s` as a String ("" if empty).
/// BUG: `&s[0..1]` is a BYTE slice - it panics when the first char is
/// multi-byte UTF-8, and panics on an empty string.
pub fn initial(s: &str) -> String {
    s[0..1].to_string()
}

test_setup_files.tests/initial_test.rs:
use initial_char::initial;

#[test]
fn ascii_first() {
    assert_eq!(initial("hello"), "h");
}

#[test]
fn multibyte_first() {
    assert_eq!(initial("\u{00fc}ber"), "\u{00fc}"); // 'ü' is 2 bytes
}

#[test]
fn emoji_first() {
    assert_eq!(initial("\u{1F680}go"), "\u{1F680}"); // rocket is 4 bytes
}

#[test]
fn empty_is_empty() {
    assert_eq!(initial(""), "");
}

reference_solution.src/lib.rs:
/// First character of `s` as a String ("" if empty).
pub fn initial(s: &str) -> String {
    s.chars().next().map(|c| c.to_string()).unwrap_or_default()
}

